  "A:Canada destination showcase": "Pichainik ab Kanada",
  "A:Slide 1 of 9: Toronto": "Pichait 1 eng' 9: Toronto",
  "A:Slide 2 of 9: Vancouver": "Pichait 2 eng' 9: Vancouver",
  "A:Slide 3 of 9: Montreal": "Pichait 3 eng' 9: Montreal",
